const falta = ['ERPNEXT_DOMAIN', 'ERPNEXT_API_KEY', 'ERPNEXT_API_SECRET'].filter(k => !$env[k]);
if (falta.length) throw new Error('PENDENTE_CONFIGURACAO_RITMO: variáveis ausentes: ' + falta.join(', '));
const base = $env.ERPNEXT_DOMAIN.replace(/\/+$/, ''); const headers = { Authorization: 'token ' + $env.ERPNEXT_API_KEY + ':' + $env.ERPNEXT_API_SECRET };
const RT = (method, path, qs, body) => this.helpers.httpRequest({ method, url: base + path, headers, qs, body, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
const EVT = '/api/resource/Synapse%20Evento%20Pagamento';
const SLA_MS = 24 * 3600 * 1000;
const agoraMs = Date.now(); const agora = new Date(agoraMs).toISOString().slice(0, 19).replace('T', ' ');
const parseUtc = (s) => new Date(String(s).replace(' ', 'T') + 'Z').getTime();
const inb = $input.first() ? ($input.first().json || {}) : {}; const body = inb.body || {};
const soOp = String(body.op_id || (body.doc && body.doc.synapse_op_id) || '').trim() || null;    // gatilho imediato (Webhook do Ritmo na criação da POS Invoice)
const sum = { verificados: 0, reconciliados: 0, expirados: 0, alertas_enviados: 0, erros: [] };
// 1) eventos que ainda exigem ação: PENDING_MATCH, ou EXPIRED com alerta pendente. RECONCILED nunca é tocado.
const filtros = [['alerta_enviado', '=', 0], ['status', 'in', ['PENDING_MATCH', 'EXPIRED']]]; if (soOp) filtros.push(['op_id', '=', soOp]);
const eventos = []; let ini = 0;
for (;;) {
  const r = await RT('GET', EVT, { fields: JSON.stringify(['name', 'op_id', 'transaction_nsu', 'status', 'created_at', 'valor', 'alerta_enviado']), filters: JSON.stringify(filtros), order_by: 'name asc', limit_start: ini, limit_page_length: 200 });
  if (r.statusCode !== 200) throw new Error('Falha ao listar eventos no Ritmo (HTTP ' + r.statusCode + ')');
  const lote = (r.body && r.body.data) || []; if (!lote.length) break; eventos.push(...lote); ini += lote.length;
}
const alertar = async (ev) => {
  const need = ['CHATWOOT_DOMAIN', 'CHATWOOT_API_TOKEN', 'CHATWOOT_ACCOUNT_ID', 'CHATWOOT_WHATSAPP_INBOX_ID', 'CHATWOOT_ALERTA_TELEFONE'].filter(k => !$env[k]);
  if (need.length) throw new Error('PENDENTE_CONFIGURACAO_ALERTA: variáveis ausentes: ' + need.join(', '));
  const cw = $env.CHATWOOT_DOMAIN.replace(/\/+$/, '') + '/api/v1/accounts/' + $env.CHATWOOT_ACCOUNT_ID; const h = { api_access_token: $env.CHATWOOT_API_TOKEN };
  const phone = String($env.CHATWOOT_ALERTA_TELEFONE).replace(/[^\d+]/g, '');
  const msg = 'Pagamento recebido sem venda correspondente após 24h.\nop_id: ' + ev.op_id + '\ntransaction_nsu: ' + ev.transaction_nsu + '\nstatus: EXPIRED';
  let c = await this.helpers.httpRequest({ method: 'GET', url: cw + '/contacts/search', headers: h, qs: { q: phone }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let contato = c.statusCode === 200 && c.body && c.body.payload && c.body.payload[0];
  if (!contato) { c = await this.helpers.httpRequest({ method: 'POST', url: cw + '/contacts', headers: h, body: { inbox_id: Number($env.CHATWOOT_WHATSAPP_INBOX_ID), name: 'Alertas Synapse', phone_number: phone }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true }); contato = c.statusCode < 300 && c.body && ((c.body.payload && c.body.payload.contact) || c.body); }
  if (!contato || !contato.id) throw new Error('Alerta: não foi possível localizar/criar o contato no Harpa (HTTP ' + c.statusCode + ')');
  const ci = (contato.contact_inboxes || []).find(x => x.inbox && String(x.inbox.id) === String($env.CHATWOOT_WHATSAPP_INBOX_ID)); const source_id = ci ? ci.source_id : undefined;
  const cv = await this.helpers.httpRequest({ method: 'POST', url: cw + '/conversations', headers: h, body: { inbox_id: Number($env.CHATWOOT_WHATSAPP_INBOX_ID), contact_id: contato.id, source_id, message: { content: msg } }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
  if (cv.statusCode >= 300) throw new Error('Alerta: o Harpa recusou a mensagem (HTTP ' + cv.statusCode + ')');
};
for (const ev of eventos) {
  sum.verificados++;
  try {
    let status = ev.status;
    if (status === 'PENDING_MATCH') {
      const v = await RT('GET', '/api/resource/POS%20Invoice', { fields: JSON.stringify(['name', 'docstatus', 'grand_total', 'rounded_total']), filters: JSON.stringify([['synapse_op_id', '=', ev.op_id]]), limit_page_length: 2 });
      if (v.statusCode !== 200) throw new Error('consulta da venda falhou (HTTP ' + v.statusCode + ')');
      const venda = ((v.body && v.body.data) || [])[0];
      const total = venda ? Number(venda.rounded_total || venda.grand_total || 0) : null;
      const confere = !!venda && venda.docstatus !== 2 && (ev.valor === null || ev.valor === undefined || Math.abs(Math.round(total * 100) - Math.round(Number(ev.valor) * 100)) <= 1);
      if (confere) {                                                           // PENDING_MATCH → RECONCILED (idempotente: a venda/pagamento já existem; nada é criado)
        const u = await RT('PUT', EVT + '/' + encodeURIComponent(ev.name), null, { status: 'RECONCILED', pos_invoice: venda.name, reconciled_at: agora });
        if (u.statusCode >= 300) throw new Error('falha ao marcar RECONCILED (HTTP ' + u.statusCode + ')');
        sum.reconciliados++; continue;
      }
      if (agoraMs - parseUtc(ev.created_at) >= SLA_MS) {                       // PENDING_MATCH → EXPIRED (24h a partir de created_at); o evento NUNCA é apagado
        const u = await RT('PUT', EVT + '/' + encodeURIComponent(ev.name), null, { status: 'EXPIRED', expired_at: agora, observacao: 'Pagamento recebido sem venda correspondente após 24h.' });
        if (u.statusCode >= 300) throw new Error('falha ao marcar EXPIRED (HTTP ' + u.statusCode + ')');
        sum.expirados++; status = 'EXPIRED';
      }
    }
    if (status === 'EXPIRED') {                                                // alerta de exceção (Harpa); só marca alerta_enviado se o envio deu certo
      await alertar(ev);
      const u = await RT('PUT', EVT + '/' + encodeURIComponent(ev.name), null, { alerta_enviado: 1 });
      if (u.statusCode >= 300) throw new Error('alerta enviado, mas falhou ao marcar alerta_enviado (HTTP ' + u.statusCode + ')');
      sum.alertas_enviados++;
    }
  } catch (e) { sum.erros.push({ op_id: ev.op_id, erro: String(e.message || e).slice(0, 200) }); }
}
// falha VISÍVEL (execução em erro no n8n) se algo ficou pendente — nunca silencioso
if (sum.erros.length) throw new Error('Reconciliador concluiu com pendências: ' + JSON.stringify(sum));
return [{ json: sum }];
